<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject\TemplateVariableValueVO;

trait TemplateVariableValueAttributeHolder
{
    protected TemplateVariableValueVO|string|null $value = null;
    protected bool $valueAssigned = false;

    public function getValueOrDefault(?TemplateVariableValueVO $value): ?TemplateVariableValueVO
    {
        return $this->valueAssigned ? ($this->value !== null ? TemplateVariableValueVO::from($this->value) : null) : $value;
    }
    public function value(TemplateVariableValueVO|string|null $value): static
    {
        $this->value = $value;
        $this->valueAssigned = true;
        return $this;
    }
    public function getValue(): ?string
    {
        return $this->value instanceof TemplateVariableValueVO ? $this->value->value() : $this->value;
    }
    public function isValueAssigned(): bool
    {
        return $this->valueAssigned;
    }
    public function writeValueTo(mixed $att): void
    {
        if ($this->valueAssigned) {
            $att->value($this->value);
        }
    }
    public function readValueFrom(mixed $att): void
    {
        if ($att->isValueAssigned()) {
            $value = $att->getValue();
            $this->value($value);
        }
    }
    public function unsetValue(): static
    {
        $this->valueAssigned = false;
        return $this;
    }
    protected function withDefaultValue(): void
    {
    }
    protected function withAssertedValueRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->valueAssigned = $this->valueAssigned) {
            $value->value = TemplateVariableValueVO::tryFrom($this->value, $errorsList);
        }
    }
}
